"""Teamwork transport — REST API v3 for task/milestone/tag operations.

Uses the Teamwork Projects API v3 with Basic Auth (API key).
Auth: TEAMWORK_API_KEY env var + site_name/project_id from config.

API docs: https://apidocs.teamwork.com/
"""

import base64
import json
import os
import urllib.error
import urllib.parse
import urllib.request
from typing import Optional

from ..base import AdapterError, AdapterAuthError, AdapterOfflineError


class TeamworkTransport:
    """Transport layer for Teamwork operations via REST API v3.

    Uses urllib.request (stdlib) — no external dependencies.
    Auth: Basic Auth with TEAMWORK_API_KEY as username, 'x' as password.
    """

    def __init__(self, site_name: str, project_id: int):
        """Initialize with Teamwork site name and project ID.

        Args:
            site_name: Teamwork subdomain, e.g. 'mycompany' for mycompany.teamwork.com
            project_id: Numeric Teamwork project ID
        """
        self.site_name = site_name
        self.project_id = project_id
        self._api_available: Optional[bool] = None
        self._base_url = f"https://{site_name}.teamwork.com/projects/api/v3" if site_name else ""
        self._v1_base_url = f"https://{site_name}.teamwork.com" if site_name else ""
        self._tags_cache: Optional[dict[str, int]] = None  # name -> tag_id

    # ── Auth ─────────────────────────────────────────────────

    def check_api(self) -> bool:
        """Check if Teamwork API is configured via env vars."""
        if self._api_available is not None:
            return self._api_available
        api_key = os.environ.get("TEAMWORK_API_KEY", "")
        self._api_available = bool(api_key and self.site_name and self.project_id)
        return self._api_available

    def health_check(self) -> dict:
        api = self.check_api()
        return {
            "status": "ok" if api else "offline",
            "api": api,
            "site": self.site_name,
            "project_id": self.project_id,
        }

    def current_user(self) -> str:
        """Resolve the authenticated Teamwork person id (for `--mine`).

        Teamwork stores assignees as numeric person ids, so the cross-backend
        `currentUser()` sentinel must be resolved to the caller's own id before
        filtering — comparing the literal sentinel matches nothing.
        """
        resp = self._v1_api_call("GET", "/me.json")
        person = resp.get("person") if isinstance(resp, dict) else None
        pid = person.get("id") if isinstance(person, dict) else None
        if pid in (None, ""):
            raise AdapterError(
                "Could not resolve the authenticated Teamwork user for --mine "
                "(/me.json returned no person id). Check TEAMWORK_API_KEY."
            )
        return str(pid)

    # ── Tasks ────────────────────────────────────────────────

    def create_task(self, task_list_id: int, name: str,
                    description: str = "",
                    parent_task_id: Optional[int] = None,
                    tag_ids: Optional[list[int]] = None,
                    priority: Optional[str] = None,
                    milestone_id: Optional[int] = None) -> dict:
        """Create a task in a task list. Returns the task JSON."""
        body: dict = {
            "task": {
                "name": name,
            }
        }
        if description:
            body["task"]["description"] = description
        if parent_task_id:
            body["task"]["parentTaskId"] = parent_task_id
        if tag_ids:
            body["task"]["tagIds"] = tag_ids
        if priority:
            body["task"]["priority"] = priority
        if milestone_id:
            body["task"]["milestoneId"] = milestone_id

        result = self._api_call("POST", f"/tasklists/{task_list_id}/tasks.json", body=body)
        task = result.get("task", result)
        return task

    def get_task(self, task_id: int) -> dict:
        """Get a task by ID."""
        result = self._api_call("GET", f"/tasks/{task_id}.json")
        return result.get("task", result)

    def update_task(self, task_id: int, **fields) -> dict:
        """Update task fields."""
        body: dict = {"task": {}}
        field_map = {
            "name": "name",
            "description": "description",
            "priority": "priority",
            "milestoneId": "milestoneId",
            "parentTaskId": "parentTaskId",
            "tagIds": "tagIds",
        }
        for key, api_key in field_map.items():
            if key in fields:
                body["task"][api_key] = fields[key]

        if body["task"]:
            self._api_call("PATCH", f"/tasks/{task_id}.json", body=body)
        return self.get_task(task_id)

    def complete_task(self, task_id: int) -> dict:
        """Mark a task as completed."""
        self._v1_api_call("PUT", f"/tasks/{task_id}/complete.json")
        return self.get_task(task_id)

    def uncomplete_task(self, task_id: int) -> dict:
        """Mark a task as not completed (reopen)."""
        self._v1_api_call("PUT", f"/tasks/{task_id}/uncomplete.json")
        return self.get_task(task_id)

    def list_tasks(self, project_id: Optional[int] = None,
                   tag_ids: Optional[list[int]] = None,
                   parent_task_id: Optional[int] = None,
                   milestone_id: Optional[int] = None,
                   tasklist_id: Optional[int] = None,
                   include_completed: bool = True,
                   page: int = 1,
                   page_size: int = 250) -> list[dict]:
        """List tasks with filters. Handles pagination automatically.

        `tasklist_id` (multi-spec support, v2.8+): narrow to a single
        tasklist via the v3 `tasklistIds=` query param. Equivalent to the
        legacy `/tasklists/{id}/tasks.json` endpoint but composes with
        the other filters (tag, milestone, parent).
        """
        pid = project_id or self.project_id
        params: dict = {
            "projectIds": str(pid),
            "page": str(page),
            "pageSize": str(page_size),
        }
        params["includeCompletedTasks"] = "true" if include_completed else "false"
        if tag_ids:
            params["tagIds"] = ",".join(str(t) for t in tag_ids)
        if parent_task_id:
            params["parentTaskId"] = str(parent_task_id)
        if tasklist_id is not None:
            params["tasklistIds"] = str(tasklist_id)
        # #122: filter by milestone server-side via the v3 `milestoneIds=` query
        # param. The previous code filtered client-side by reading
        # `task.milestoneId` from each row, but v3 responses don't include
        # that field on task objects (only `dueDateFromMilestone: bool`), so
        # the filter excluded every task and `get-sprint-backlog` returned
        # `[]` for projects organising sprints as milestones.
        if milestone_id is not None:
            params["milestoneIds"] = str(milestone_id)

        result = self._api_call("GET", "/tasks.json", params=params)
        tasks = result.get("tasks", [])

        # Auto-paginate if we got a full page
        if len(result.get("tasks", [])) >= page_size:
            more = self.list_tasks(
                project_id=pid, tag_ids=tag_ids,
                parent_task_id=parent_task_id, milestone_id=milestone_id,
                tasklist_id=tasklist_id,
                include_completed=include_completed,
                page=page + 1, page_size=page_size,
            )
            tasks.extend(more)

        return tasks

    def move_workflow_stage(self, task_id: int, stage_id: int,
                            workflow_id: Optional[int] = None) -> None:
        """Move a task to a workflow stage (board column).

        This changes the board column position, NOT the task completion status.
        Use complete_task()/uncomplete_task() separately if needed.

        Uses: POST /workflows/{workflowId}/stages/{stageId}/tasks.json
        with body {"taskIds": [taskId]}.

        Args:
            task_id: Teamwork task ID
            stage_id: Target workflow stage ID
            workflow_id: Workflow ID (auto-detected from project if not provided)
        """
        if workflow_id is None:
            workflow_id = self._detect_workflow_id()
            if workflow_id is None:
                return  # No workflow configured — skip silently

        body = {"taskIds": [task_id]}
        self._api_call("POST",
                        f"/workflows/{workflow_id}/stages/{stage_id}/tasks.json",
                        body=body)

    def _detect_workflow_id(self) -> Optional[int]:
        """Detect the first active workflow for this project."""
        result = self._api_call(
            "GET", f"/projects/{self.project_id}/workflows.json",
        )
        workflows = result.get("workflows", [])
        for wf in workflows:
            if wf.get("status") == "active":
                return wf.get("id")
        return workflows[0].get("id") if workflows else None

    def get_workflow_stages(self, project_id: Optional[int] = None) -> list[dict]:
        """List workflow stages for the project. Returns stages with task assignments."""
        pid = project_id or self.project_id
        result = self._api_call(
            "GET", f"/projects/{pid}/workflows.json",
        )
        workflows = result.get("workflows", [])
        if not workflows:
            return []
        # Get first workflow's stages with full detail
        wf_id = workflows[0].get("id")
        if not wf_id:
            return []
        detail = self._api_call("GET", f"/workflows/{wf_id}.json?include=stages")
        stages_map = detail.get("included", {}).get("stages", {})
        return list(stages_map.values())

    def delete_task(self, task_id: int) -> None:
        """Delete a task."""
        self._api_call("DELETE", f"/tasks/{task_id}.json")

    # ── Tags ─────────────────────────────────────────────────

    def create_tag(self, name: str, color: Optional[str] = None) -> dict:
        """Create a tag. Returns the tag dict."""
        body: dict = {"tag": {"name": name}}
        if color:
            body["tag"]["color"] = color
        result = self._api_call("POST", "/tags.json", body=body)
        tag = result.get("tag", result)
        # Update cache
        if self._tags_cache is not None and tag.get("id"):
            self._tags_cache[name] = tag["id"]
        return tag

    def list_tags(self) -> list[dict]:
        """List all tags. Caches the result."""
        result = self._api_call("GET", "/tags.json")
        tags = result.get("tags", [])
        # Populate cache
        self._tags_cache = {t.get("name", ""): t.get("id", 0) for t in tags}
        return tags

    def get_or_create_tag(self, name: str) -> int:
        """Get a tag ID by name, creating it if it doesn't exist."""
        # Check cache
        if self._tags_cache is None:
            self.list_tags()
        if self._tags_cache and name in self._tags_cache:
            return self._tags_cache[name]

        # Create
        tag = self.create_tag(name)
        tag_id = tag.get("id", 0)
        if self._tags_cache is not None:
            self._tags_cache[name] = tag_id
        return tag_id

    # ── Milestones ───────────────────────────────────────────

    def create_milestone(self, name: str, description: str = "",
                         deadline: Optional[str] = None) -> dict:
        """Create a milestone in the project."""
        body: dict = {
            "milestone": {
                "name": name,
            }
        }
        if description:
            body["milestone"]["description"] = description
        if deadline:
            body["milestone"]["deadline"] = deadline

        result = self._api_call(
            "POST", f"/projects/{self.project_id}/milestones.json", body=body,
        )
        return result.get("milestone", result)

    def list_milestones(self, include_completed: bool = True) -> list[dict]:
        """List milestones in the project."""
        params: dict = {"projectIds": str(self.project_id)}
        if not include_completed:
            params["status"] = "incomplete"
        result = self._api_call("GET", "/milestones.json", params=params)
        return result.get("milestones", [])

    def get_milestone(self, milestone_id: int) -> dict:
        """Get a milestone by ID."""
        result = self._api_call("GET", f"/milestones/{milestone_id}.json")
        return result.get("milestone", result)

    def update_milestone(self, milestone_id: int, **fields) -> dict:
        """Update milestone fields."""
        body: dict = {"milestone": {}}
        for key in ("name", "description", "deadline"):
            if key in fields:
                body["milestone"][key] = fields[key]
        if body["milestone"]:
            self._api_call("PATCH", f"/milestones/{milestone_id}.json", body=body)
        return self.get_milestone(milestone_id)

    def complete_milestone(self, milestone_id: int) -> dict:
        """Mark a milestone as completed."""
        self._v1_api_call("PUT", f"/milestones/{milestone_id}/complete.json")
        return self.get_milestone(milestone_id)

    # ── Task Lists ───────────────────────────────────────────

    def get_or_create_tasklist(self, name: str, milestone_id: Optional[int] = None) -> int:
        """Get or create a task list by name. Returns the task list ID."""
        # List existing task lists
        result = self._api_call(
            "GET", f"/projects/{self.project_id}/tasklists.json",
        )
        tasklists = result.get("tasklists", [])
        for tl in tasklists:
            if tl.get("name") == name:
                return tl["id"]

        # Create new task list
        body: dict = {"tasklist": {"name": name}}
        if milestone_id:
            body["tasklist"]["milestoneId"] = milestone_id
        result = self._api_call(
            "POST", f"/projects/{self.project_id}/tasklists.json", body=body,
        )
        tl = result.get("tasklist", result)
        return tl.get("id") or result.get("TASKLISTID", 0)

    # ── Internal ─────────────────────────────────────────────

    def _v1_api_call(self, method: str, path: str,
                     body: Optional[dict] = None,
                     params: Optional[dict] = None) -> dict:
        """Call the Teamwork REST API v1 with Basic Auth.

        Used for endpoints that only exist on v1, such as:
          PUT /tasks/{id}/complete.json
          PUT /tasks/{id}/uncomplete.json
          PUT /milestones/{id}/complete.json
        """
        if not self.check_api():
            raise AdapterOfflineError(
                "Teamwork API not configured. Required:\n"
                "  TEAMWORK_API_KEY — API key from Teamwork → Edit My Details → API tab\n"
                "  .synaptory.yaml tracker.teamwork.site_name — your Teamwork subdomain\n"
                "  .synaptory.yaml tracker.teamwork.project_id — numeric project ID\n\n"
                "Tip: use direnv for project-scoped keys:\n"
                "  echo 'export TEAMWORK_API_KEY=\"your-key\"' > .envrc && direnv allow .\n"
                "  Add .envrc to .gitignore."
            )

        api_key = os.environ["TEAMWORK_API_KEY"]
        url = f"{self._v1_base_url}{path}"
        if params:
            url += "?" + urllib.parse.urlencode(params)

        credentials = base64.b64encode(f"{api_key}:x".encode()).decode()
        headers = {
            "Authorization": f"Basic {credentials}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        }

        data = None
        if body is not None:
            data = json.dumps(body).encode("utf-8")

        req = urllib.request.Request(url, data=data, headers=headers, method=method)

        try:
            with urllib.request.urlopen(req, timeout=30) as response:
                response_body = response.read().decode("utf-8")
                if not response_body.strip():
                    return {}
                return json.loads(response_body)
        except urllib.error.HTTPError as e:
            error_body = ""
            try:
                error_body = e.read().decode("utf-8")
            except Exception:
                pass
            if e.code == 401:
                raise AdapterAuthError(
                    "Teamwork API authentication failed. Check TEAMWORK_API_KEY."
                )
            if e.code == 403:
                raise AdapterAuthError(
                    f"Teamwork API forbidden (403). Check API key permissions.\n{error_body}"
                )
            if e.code == 404:
                raise AdapterError(
                    f"Teamwork resource not found: {method} {path}\n{error_body}"
                )
            if e.code == 429:
                raise AdapterOfflineError(
                    "Teamwork API rate limit exceeded. Wait before retrying."
                )
            raise AdapterError(
                f"Teamwork API error ({e.code}): {method} {path}\n{error_body}"
            )
        except urllib.error.URLError as e:
            raise AdapterOfflineError(f"Teamwork API unreachable: {e.reason}")
        except TimeoutError:
            raise AdapterOfflineError(f"Teamwork API timed out: {method} {path}")
        except json.JSONDecodeError:
            return {}

    def _api_call(self, method: str, path: str,
                  body: Optional[dict] = None,
                  params: Optional[dict] = None) -> dict:
        """Call the Teamwork REST API v3 with Basic Auth."""
        if not self.check_api():
            raise AdapterOfflineError(
                "Teamwork API not configured. Required:\n"
                "  TEAMWORK_API_KEY — API key from Teamwork → Edit My Details → API tab\n"
                "  .synaptory.yaml tracker.teamwork.site_name — your Teamwork subdomain\n"
                "  .synaptory.yaml tracker.teamwork.project_id — numeric project ID\n\n"
                "Tip: use direnv for project-scoped keys:\n"
                "  echo 'export TEAMWORK_API_KEY=\"your-key\"' > .envrc && direnv allow .\n"
                "  Add .envrc to .gitignore."
            )

        api_key = os.environ["TEAMWORK_API_KEY"]
        url = f"{self._base_url}{path}"
        if params:
            url += "?" + urllib.parse.urlencode(params)

        # Basic Auth: api_key as username, 'x' as password
        credentials = base64.b64encode(f"{api_key}:x".encode()).decode()

        headers = {
            "Authorization": f"Basic {credentials}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        }

        data = None
        if body is not None:
            data = json.dumps(body).encode("utf-8")

        req = urllib.request.Request(url, data=data, headers=headers, method=method)

        try:
            with urllib.request.urlopen(req, timeout=30) as response:
                # Check rate limiting
                remaining = response.headers.get("X-RateLimit-Remaining")
                if remaining is not None and int(remaining) <= 0:
                    raise AdapterOfflineError(
                        "Teamwork API rate limit reached. Wait before retrying."
                    )

                response_body = response.read().decode("utf-8")
                if not response_body.strip():
                    return {}
                return json.loads(response_body)

        except urllib.error.HTTPError as e:
            error_body = ""
            try:
                error_body = e.read().decode("utf-8")
            except Exception:
                pass

            if e.code == 401:
                raise AdapterAuthError(
                    "Teamwork API authentication failed. Check TEAMWORK_API_KEY."
                )
            if e.code == 403:
                raise AdapterAuthError(
                    f"Teamwork API forbidden (403). Check API key permissions.\n{error_body}"
                )
            if e.code == 404:
                raise AdapterError(
                    f"Teamwork resource not found: {method} {path}\n{error_body}"
                )
            if e.code == 429:
                raise AdapterOfflineError(
                    "Teamwork API rate limit exceeded. Wait before retrying."
                )
            raise AdapterError(
                f"Teamwork API error ({e.code}): {method} {path}\n{error_body}"
            )
        except urllib.error.URLError as e:
            raise AdapterOfflineError(f"Teamwork API unreachable: {e.reason}")
        except TimeoutError:
            raise AdapterOfflineError(f"Teamwork API timed out: {method} {path}")
        except json.JSONDecodeError:
            if method == "DELETE":
                return {}
            raise AdapterError(f"Invalid JSON response from Teamwork: {method} {path}")
